unsafe class C
{
    public static void Main()
    {
        Fixable? f = new Fixable();

        fixed (int* p = f)
        {
            System.Console.WriteLine(p[1]);
        }
    }
}

public struct Fixable
{
    public ref int GetPinnableReference()
    {
        return ref (new int[]{1,2,3})[0];
    }
}

